INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n  <meta name="theme-color" content="#0b0f19">\n  <meta name="apple-mobile-web-app-capable" content="yes">\n  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n  <title>ASTRA Collector — Experimental Data Terminal</title>\n  <link rel="manifest" href="/static/manifest.json">\n  <link rel="stylesheet" href="/static/style.css">\n</head>\n<body>\n  <div id="app-container">\n\n    <!-- Top Status Bar -->\n    <header id="top-bar">\n      <div class="brand">\n        <span class="brand-title">ASTRA COLLECTOR</span>\n        <span class="brand-sub">BAS • SIH 26174</span>\n      </div>\n      <div id="connection-pill" class="badge badge-dim">OFFLINE</div>\n    </header>\n\n    <!-- SCREEN 1: CONNECT -->\n    <section id="screen-connect" class="screen active">\n      <div class="card terminal-card">\n        <div class="terminal-header">\n          <h2>COLLECTOR LOGIN</h2>\n          <p class="subtitle">Authenticate terminal to receive experiment runs</p>\n        </div>\n\n        <div class="form-group">\n          <label for="input-server-url">Upload API Server URL</label>\n          <input type="text" id="input-server-url" value="" placeholder="http://192.168.1.x:8000">\n        </div>\n\n        <div class="form-group">\n          <label for="input-collector-id">Synthesizer Collector ID</label>\n          <input type="text" id="input-collector-id" value="COL-007" placeholder="e.g. COL-001">\n        </div>\n\n        <div id="connect-error" class="error-banner hidden"></div>\n\n        <button id="btn-connect" class="btn btn-primary">\n          <span>CONNECT TERMINAL</span>\n        </button>\n      </div>\n    </section>\n\n    <!-- SCREEN 2: TASK ASSIGNMENT -->\n    <section id="screen-task" class="screen">\n      <div class="task-summary-card">\n        <div class="task-meta-row">\n          <div>\n            <h2 id="task-run-title">EXP001 • RUN-0042</h2>\n            <p id="task-camera-sub" class="subtitle">Camera: CAM-01 (1080p Landscape)</p>\n          </div>\n          <span id="task-scenario-badge" class="badge badge-nominal">NOMINAL</span>\n        </div>\n\n        <div class="parameters-grid">\n          <div class="param-box">\n            <span class="param-label">REQUIRED OBJECT</span>\n            <span id="task-obj-val" class="param-val">RED_COMPONENT</span>\n          </div>\n          <div class="param-box">\n            <span class="param-label">TARGET LOCATION</span>\n            <span id="task-tgt-val" class="param-val">TARGET_A</span>\n          </div>\n          <div class="param-box">\n            <span class="param-label">DURATION BOUNDS</span>\n            <span id="task-dur-val" class="param-val">30–60s</span>\n          </div>\n        </div>\n      </div>\n\n      <div class="card procedure-card">\n        <div class="section-title">\n          <span>PROCEDURE PROTOCOL (<span id="task-proto-ver">EXP001-v1.0</span>)</span>\n        </div>\n        <ol id="task-steps-list" class="steps-list">\n          <!-- Populated dynamically -->\n        </ol>\n      </div>\n\n      <div class="bottom-action-bar">\n        <button id="btn-start-recording" class="btn btn-primary btn-cta">\n          <svg class="icon" viewBox="0 0 24 24" fill="currentColor"><path d="M17 10.5V7c0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4z"/></svg>\n          <span>START RECORDING</span>\n        </button>\n      </div>\n    </section>\n\n    <!-- SCREEN 3: CAMERA RECORDING -->\n    <section id="screen-camera" class="screen">\n      <div class="viewfinder-wrapper">\n        <video id="viewfinder" autoplay playsinline muted></video>\n        \n        <!-- Camera HUD Overlays -->\n        <div class="camera-hud-top">\n          <div class="hud-pill" id="hud-task-tag">EXP001 • RUN-0042 • CAM-01</div>\n          <div class="rec-pill">\n            <span class="rec-dot"></span>\n            <span id="rec-timer">REC 00:00</span>\n          </div>\n        </div>\n\n        <div class="camera-hud-bottom">\n          <button id="btn-stop-recording" class="btn btn-danger btn-rec-stop">\n            <svg class="icon" viewBox="0 0 24 24" fill="currentColor"><path d="M6 6h12v12H6z"/></svg>\n            <span>STOP RECORDING</span>\n          </button>\n        </div>\n      </div>\n    </section>\n\n    <!-- SCREEN 4: REVIEW & VALIDATE -->\n    <section id="screen-review" class="screen">\n      <div class="card review-card">\n        <h2>RECORDING VALIDATION</h2>\n        <p id="review-task-sub" class="subtitle">EXP001 • RUN-0042 • CAM-01</p>\n\n        <div class="video-preview-box">\n          <video id="review-player" controls playsinline></video>\n        </div>\n\n        <div class="validation-checklist">\n          <div class="check-item" id="check-duration">\n            <div class="check-text">\n              <span class="check-title">DURATION</span>\n              <span id="val-duration" class="check-sub">Calculating...</span>\n            </div>\n            <span id="icon-duration" class="check-status">✓</span>\n          </div>\n\n          <div class="check-item">\n            <div class="check-text">\n              <span class="check-title">RESOLUTION & FRAMING</span>\n              <span class="check-sub">1080p Landscape Viewport</span>\n            </div>\n            <span class="check-status check-ok">✓</span>\n          </div>\n\n          <div class="check-item">\n            <div class="check-text">\n              <span class="check-title">FILE SIZE</span>\n              <span id="val-file-size" class="check-sub">Calculating...</span>\n            </div>\n            <span class="check-status check-ok">✓</span>\n          </div>\n\n          <div class="check-item check-column">\n            <span class="check-title">CRYPTOGRAPHIC SHA-256 DIGEST</span>\n            <span id="val-sha256" class="hash-display">Computing streaming hash...</span>\n          </div>\n        </div>\n\n        <div class="actions-row">\n          <button id="btn-rerecord" class="btn btn-secondary">\n            <span>RE-RECORD</span>\n          </button>\n          <button id="btn-upload" class="btn btn-primary" disabled>\n            <span>UPLOAD TO CLOUD</span>\n          </button>\n        </div>\n      </div>\n    </section>\n\n    <!-- SCREEN 5: UPLOAD PROGRESS -->\n    <section id="screen-upload" class="screen">\n      <div class="card upload-card">\n        <div class="upload-header">\n          <div id="upload-status-icon" class="status-icon-box">☁</div>\n          <h2 id="upload-status-title">STREAMING CHUNKS...</h2>\n          <p id="upload-task-sub" class="subtitle">EXP001 • RUN-0042</p>\n        </div>\n\n        <div class="progress-container">\n          <div class="progress-bar-track">\n            <div id="upload-progress-fill" class="progress-bar-fill" style="width: 0%;"></div>\n          </div>\n          <div class="progress-meta">\n            <span id="upload-progress-chunk">Chunk 0 of 0</span>\n            <span id="upload-progress-percent">0%</span>\n          </div>\n        </div>\n\n        <div id="upload-error-box" class="error-banner hidden">\n          <span id="upload-error-msg">Upload failed.</span>\n          <p class="safe-note">Local recording is safely retained in temporary browser storage.</p>\n        </div>\n\n        <button id="btn-retry-upload" class="btn btn-primary hidden">\n          <span>RETRY UPLOAD</span>\n        </button>\n      </div>\n    </section>\n\n    <!-- SCREEN 6: COMPLETION -->\n    <section id="screen-complete" class="screen">\n      <div class="card complete-card">\n        <div class="complete-badge">✓</div>\n        <h2>DATASET UPLOAD VERIFIED</h2>\n        <p id="complete-task-sub" class="subtitle">RUN-0042 (CAM-01) Complete</p>\n\n        <div class="verified-box">\n          <span class="box-label">REMOTE HUGGING FACE TARGET</span>\n          <span id="complete-remote-path" class="remote-path-val">videos/exp001/RUN-0042/CAM-01.mp4</span>\n        </div>\n\n        <div class="cleanup-box">\n          <span class="cleanup-icon">🗑</span>\n          <div class="cleanup-info">\n            <span class="box-label">LOCAL TEMPORARY STORAGE</span>\n            <span class="cleanup-status">IndexedDB cache verified clean & purged</span>\n          </div>\n        </div>\n\n        <button id="btn-next-task" class="btn btn-primary btn-cta">\n          <span>DISPENSE NEXT TASK →</span>\n        </button>\n      </div>\n    </section>\n\n  </div>\n\n  <script src="/static/app.js"></script>\n</body>\n</html>\n'

STYLE_CSS = "/* ASTRA Collector Web App Styling */\n:root {\n  --bg-space: #0B0F19;\n  --surface-dark: #141B2D;\n  --surface-card: #1F2940;\n  --cyan-accent: #00E5FF;\n  --cyan-dim: #00838F;\n  --green-success: #00E676;\n  --amber-warning: #FFD600;\n  --red-critical: #FF1744;\n  --text-primary: #ECEFF1;\n  --text-secondary: #90A4AE;\n  --font-mono: 'Consolas', 'Courier New', monospace;\n  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n  -webkit-tap-highlight-color: transparent;\n}\n\nbody {\n  background-color: var(--bg-space);\n  color: var(--text-primary);\n  font-family: var(--font-sans);\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  overflow-x: hidden;\n}\n\n#app-container {\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n  max-width: 900px;\n  margin: 0 auto;\n  width: 100%;\n}\n\n/* Header */\n#top-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 14px 20px;\n  background: var(--surface-dark);\n  border-bottom: 1px solid var(--surface-card);\n}\n\n.brand-title {\n  font-family: var(--font-mono);\n  font-weight: 700;\n  font-size: 16px;\n  color: var(--cyan-accent);\n  letter-spacing: 1px;\n}\n\n.brand-sub {\n  font-size: 11px;\n  color: var(--text-secondary);\n  display: block;\n}\n\n/* Badges */\n.badge {\n  padding: 4px 10px;\n  border-radius: 6px;\n  font-size: 11px;\n  font-weight: 700;\n  font-family: var(--font-mono);\n  letter-spacing: 0.5px;\n}\n\n.badge-dim {\n  background: var(--surface-card);\n  color: var(--text-secondary);\n}\n\n.badge-active {\n  background: rgba(0, 229, 255, 0.15);\n  color: var(--cyan-accent);\n  border: 1px solid var(--cyan-accent);\n}\n\n.badge-nominal {\n  background: rgba(0, 230, 118, 0.15);\n  color: var(--green-success);\n  border: 1px solid var(--green-success);\n}\n\n.badge-fault {\n  background: rgba(255, 214, 0, 0.15);\n  color: var(--amber-warning);\n  border: 1px solid var(--amber-warning);\n}\n\n/* Screen Transitions */\n.screen {\n  display: none;\n  flex-direction: column;\n  flex: 1;\n  padding: 20px;\n}\n\n.screen.active {\n  display: flex;\n}\n\n/* Cards */\n.card {\n  background: var(--surface-dark);\n  border: 1px solid var(--surface-card);\n  border-radius: 16px;\n  padding: 24px;\n  margin-bottom: 16px;\n}\n\n.subtitle {\n  color: var(--text-secondary);\n  font-size: 13px;\n  margin-top: 4px;\n}\n\n/* Forms */\n.form-group {\n  margin-top: 18px;\n}\n\n.form-group label {\n  display: block;\n  font-size: 12px;\n  color: var(--text-secondary);\n  font-weight: 600;\n  margin-bottom: 6px;\n  text-transform: uppercase;\n}\n\n.form-group input {\n  width: 100%;\n  padding: 14px 16px;\n  background: var(--surface-card);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: 8px;\n  color: var(--text-primary);\n  font-size: 15px;\n  font-family: var(--font-mono);\n  outline: none;\n  transition: border-color 0.2s;\n}\n\n.form-group input:focus {\n  border-color: var(--cyan-accent);\n}\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 14px 24px;\n  border-radius: 10px;\n  font-size: 15px;\n  font-weight: 700;\n  cursor: pointer;\n  border: none;\n  transition: all 0.2s;\n  font-family: var(--font-sans);\n}\n\n.btn-primary {\n  background: var(--cyan-accent);\n  color: var(--bg-space);\n  width: 100%;\n  margin-top: 24px;\n}\n\n.btn-primary:active {\n  transform: scale(0.98);\n}\n\n.btn-primary:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n.btn-secondary {\n  background: var(--surface-card);\n  color: var(--text-primary);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  flex: 1;\n}\n\n.btn-danger {\n  background: var(--red-critical);\n  color: white;\n}\n\n.btn-cta {\n  height: 54px;\n  font-size: 16px;\n}\n\n.icon {\n  width: 20px;\n  height: 20px;\n  margin-right: 8px;\n}\n\n/* Error Banner */\n.error-banner {\n  background: rgba(255, 23, 68, 0.15);\n  border: 1px solid var(--red-critical);\n  color: #FF8A80;\n  padding: 12px 16px;\n  border-radius: 8px;\n  font-size: 13px;\n  margin-top: 16px;\n}\n\n.hidden {\n  display: none !important;\n}\n\n/* Task Screen */\n.task-summary-card {\n  background: var(--surface-dark);\n  border: 1px solid var(--surface-card);\n  border-radius: 16px;\n  padding: 20px;\n  margin-bottom: 16px;\n}\n\n.task-meta-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n\n.task-meta-row h2 {\n  font-family: var(--font-mono);\n  font-size: 20px;\n  color: var(--cyan-accent);\n}\n\n.parameters-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 10px;\n  background: var(--surface-card);\n  padding: 12px;\n  border-radius: 10px;\n}\n\n.param-box {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n}\n\n.param-label {\n  font-size: 10px;\n  color: var(--text-secondary);\n  font-weight: 700;\n}\n\n.param-val {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--text-primary);\n  margin-top: 4px;\n}\n\n.procedure-card {\n  flex: 1;\n  overflow-y: auto;\n  max-height: 48vh;\n}\n\n.section-title {\n  font-size: 12px;\n  font-weight: 700;\n  color: var(--text-secondary);\n  letter-spacing: 0.5px;\n  margin-bottom: 12px;\n}\n\n.steps-list {\n  padding-left: 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n.steps-list li::marker {\n  color: var(--cyan-accent);\n  font-weight: 700;\n}\n\n/* Camera Screen Viewfinder */\n#screen-camera {\n  padding: 0;\n  position: relative;\n  background: black;\n  min-height: 100vh;\n}\n\n.viewfinder-wrapper {\n  position: relative;\n  width: 100vw;\n  height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n}\n\n#viewfinder {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.camera-hud-top {\n  position: absolute;\n  top: 20px;\n  left: 20px;\n  right: 20px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  z-index: 10;\n}\n\n.hud-pill {\n  background: rgba(0, 0, 0, 0.7);\n  border: 1px solid var(--surface-card);\n  padding: 8px 16px;\n  border-radius: 8px;\n  font-family: var(--font-mono);\n  font-size: 13px;\n  color: var(--cyan-accent);\n  font-weight: 700;\n}\n\n.rec-pill {\n  background: rgba(0, 0, 0, 0.7);\n  border: 1px solid rgba(255, 23, 68, 0.5);\n  padding: 8px 16px;\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  font-family: var(--font-mono);\n  font-size: 14px;\n  font-weight: 700;\n  color: white;\n}\n\n.rec-dot {\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n  background: var(--red-critical);\n  margin-right: 8px;\n  animation: recBlink 1s infinite alternate;\n}\n\n@keyframes recBlink {\n  from { opacity: 1; }\n  to { opacity: 0.2; }\n}\n\n.camera-hud-bottom {\n  position: absolute;\n  bottom: 30px;\n  left: 0;\n  right: 0;\n  display: flex;\n  justify-content: center;\n  z-index: 10;\n}\n\n.btn-rec-stop {\n  padding: 16px 36px;\n  border-radius: 14px;\n  font-size: 16px;\n  font-weight: 700;\n  box-shadow: 0 4px 20px rgba(255, 23, 68, 0.4);\n}\n\n/* Review Screen */\n.video-preview-box {\n  width: 100%;\n  border-radius: 12px;\n  overflow: hidden;\n  background: black;\n  margin: 16px 0;\n  max-height: 240px;\n}\n\n#review-player {\n  width: 100%;\n  max-height: 240px;\n  object-fit: contain;\n}\n\n.validation-checklist {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin: 16px 0;\n}\n\n.check-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 10px 14px;\n  background: var(--surface-card);\n  border-radius: 8px;\n}\n\n.check-column {\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 6px;\n}\n\n.check-title {\n  font-size: 11px;\n  color: var(--text-secondary);\n  font-weight: 700;\n  display: block;\n}\n\n.check-sub {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text-primary);\n}\n\n.check-status {\n  font-weight: 700;\n  color: var(--green-success);\n}\n\n.hash-display {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--cyan-accent);\n  word-break: break-all;\n}\n\n.actions-row {\n  display: flex;\n  gap: 12px;\n  margin-top: 16px;\n}\n\n.actions-row .btn {\n  margin-top: 0;\n}\n\n/* Upload Screen */\n.upload-card, .complete-card {\n  text-align: center;\n  padding: 36px 24px;\n}\n\n.status-icon-box {\n  font-size: 48px;\n  color: var(--cyan-accent);\n  margin-bottom: 16px;\n}\n\n.progress-container {\n  margin: 28px 0;\n}\n\n.progress-bar-track {\n  width: 100%;\n  height: 10px;\n  background: var(--surface-card);\n  border-radius: 5px;\n  overflow: hidden;\n}\n\n.progress-bar-fill {\n  height: 100%;\n  background: var(--cyan-accent);\n  transition: width 0.2s ease;\n}\n\n.progress-meta {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 8px;\n  font-size: 13px;\n  color: var(--text-secondary);\n  font-family: var(--font-mono);\n}\n\n.safe-note {\n  font-size: 12px;\n  color: var(--text-secondary);\n  margin-top: 6px;\n}\n\n/* Completion Screen */\n.complete-badge {\n  width: 64px;\n  height: 64px;\n  border-radius: 50%;\n  background: rgba(0, 230, 118, 0.15);\n  border: 2px solid var(--green-success);\n  color: var(--green-success);\n  font-size: 32px;\n  font-weight: 700;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0 auto 20px auto;\n}\n\n.verified-box, .cleanup-box {\n  background: var(--surface-card);\n  padding: 14px;\n  border-radius: 10px;\n  text-align: left;\n  margin-top: 14px;\n}\n\n.cleanup-box {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.cleanup-icon {\n  font-size: 22px;\n}\n\n.box-label {\n  font-size: 11px;\n  color: var(--text-secondary);\n  font-weight: 700;\n  display: block;\n}\n\n.remote-path-val {\n  font-family: var(--font-mono);\n  font-size: 13px;\n  color: var(--cyan-accent);\n  display: block;\n  margin-top: 4px;\n  word-break: break-all;\n}\n\n.cleanup-status {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text-primary);\n}\n"

APP_JS = "/**\n * ASTRA Collector — Mobile Web Terminal Controller\n * Features:\n * - HTML5 MediaRecorder (1080p Landscape)\n * - IndexedDB Staging & Fail-Closed Storage Invariant\n * - Web Crypto API Streaming SHA-256\n * - Resumable 8 MB Chunked Streaming\n */\n\nclass IndexedDBManager {\n  constructor() {\n    this.dbName = 'astra_collector_db';\n    this.version = 1;\n    this.db = null;\n  }\n\n  async init() {\n    return new Promise((resolve, reject) => {\n      const request = indexedDB.open(this.dbName, this.version);\n      request.onupgradeneeded = (e) => {\n        const db = e.target.result;\n        if (!db.objectStoreNames.contains('recordings')) {\n          db.createObjectStore('recordings', { keyPath: 'recordingId' });\n        }\n      };\n      request.onsuccess = (e) => {\n        this.db = e.target.result;\n        resolve(this.db);\n      };\n      request.onerror = (e) => reject(e.target.error);\n    });\n  }\n\n  async saveVideoBlob(recordingId, blob, metadata) {\n    if (!this.db) await this.init();\n    return new Promise((resolve, reject) => {\n      const tx = this.db.transaction('recordings', 'readwrite');\n      const store = tx.objectStore('recordings');\n      store.put({ recordingId, blob, metadata, timestamp: Date.now() });\n      tx.oncomplete = () => resolve();\n      tx.onerror = (e) => reject(e.target.error);\n    });\n  }\n\n  async getVideoBlob(recordingId) {\n    if (!this.db) await this.init();\n    return new Promise((resolve, reject) => {\n      const tx = this.db.transaction('recordings', 'readonly');\n      const store = tx.objectStore('recordings');\n      const req = store.get(recordingId);\n      req.onsuccess = () => resolve(req.result);\n      req.onerror = (e) => reject(e.target.error);\n    });\n  }\n\n  /**\n   * CRITICAL INVARIANT:\n   * Only delete the video from local IndexedDB if server status is VERIFIED.\n   */\n  async deleteVerifiedVideo(recordingId, serverStatus, isVerified) {\n    if (!isVerified || String(serverStatus).toLowerCase() !== 'verified') {\n      throw new Error(`CRITICAL INVARIANT VIOLATION: Cannot delete unverified local recording (isVerified=${isVerified}, status=${serverStatus})`);\n    }\n    if (!this.db) await this.init();\n    return new Promise((resolve, reject) => {\n      const tx = this.db.transaction('recordings', 'readwrite');\n      const store = tx.objectStore('recordings');\n      store.delete(recordingId);\n      tx.oncomplete = () => {\n        console.log(`[Storage] Securely purged local recording ${recordingId} after verified upload.`);\n        resolve(true);\n      };\n      tx.onerror = (e) => reject(e.target.error);\n    });\n  }\n}\n\nclass ChecksumManager {\n  static async computeSha256(blob) {\n    const arrayBuffer = await blob.arrayBuffer();\n    const digestBuffer = await crypto.subtle.digest('SHA-256', arrayBuffer);\n    const hashArray = Array.from(new Uint8Array(digestBuffer));\n    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');\n  }\n}\n\nclass CameraCaptureManager {\n  constructor() {\n    this.stream = null;\n    this.mediaRecorder = null;\n    this.recordedChunks = [];\n    this.timerInterval = null;\n    this.durationSeconds = 0;\n  }\n\n  async startCamera(videoElement) {\n    const constraints = {\n      audio: true,\n      video: {\n        width: { ideal: 1920 },\n        height: { ideal: 1080 },\n        facingMode: { ideal: 'environment' }\n      }\n    };\n    this.stream = await navigator.mediaDevices.getUserMedia(constraints);\n    videoElement.srcObject = this.stream;\n    await videoElement.play();\n  }\n\n  stopCamera() {\n    if (this.stream) {\n      this.stream.getTracks().forEach(track => track.stop());\n      this.stream = null;\n    }\n  }\n\n  startRecording(onTick) {\n    this.recordedChunks = [];\n    this.durationSeconds = 0;\n\n    let mimeType = 'video/webm;codecs=vp9,opus';\n    if (!MediaRecorder.isTypeSupported(mimeType)) {\n      mimeType = MediaRecorder.isTypeSupported('video/mp4') ? 'video/mp4' : 'video/webm';\n    }\n\n    this.mediaRecorder = new MediaRecorder(this.stream, {\n      mimeType: mimeType,\n      videoBitsPerSecond: 8000000 // 8 Mbps high quality\n    });\n\n    this.mediaRecorder.ondataavailable = (e) => {\n      if (e.data && e.data.size > 0) {\n        this.recordedChunks.push(e.data);\n      }\n    };\n\n    this.mediaRecorder.start(1000); // 1-second chunks\n\n    this.timerInterval = setInterval(() => {\n      this.durationSeconds++;\n      if (onTick) onTick(this.durationSeconds);\n    }, 1000);\n  }\n\n  async stopRecording() {\n    return new Promise((resolve) => {\n      clearInterval(this.timerInterval);\n      this.mediaRecorder.onstop = () => {\n        const mimeType = this.mediaRecorder.mimeType || 'video/webm';\n        const blob = new Blob(this.recordedChunks, { type: mimeType });\n        this.stopCamera();\n        resolve({ blob, durationSeconds: this.durationSeconds });\n      };\n      this.mediaRecorder.stop();\n    });\n  }\n}\n\n// App State\nconst state = {\n  serverUrl: window.location.origin,\n  collectorId: 'COL-007',\n  authToken: null,\n  activeTask: null,\n  activeBlob: null,\n  activeDuration: 0,\n  activeSha256: null,\n  activeUploadId: null\n};\n\n// DOM References\nconst screens = {\n  connect: document.getElementById('screen-connect'),\n  task: document.getElementById('screen-task'),\n  camera: document.getElementById('screen-camera'),\n  review: document.getElementById('screen-review'),\n  upload: document.getElementById('screen-upload'),\n  complete: document.getElementById('screen-complete')\n};\n\nconst storageManager = new IndexedDBManager();\nconst cameraManager = new CameraCaptureManager();\n\nfunction showScreen(screenKey) {\n  Object.values(screens).forEach(s => s.classList.remove('active'));\n  if (screens[screenKey]) {\n    screens[screenKey].classList.add('active');\n  }\n}\n\n// ----------------------------------------------------------------------------\n// Screen 1: Connect Logic\n// ----------------------------------------------------------------------------\ndocument.getElementById('input-server-url').value = window.location.origin;\n\ndocument.getElementById('btn-connect').addEventListener('click', async () => {\n  const serverUrlInput = document.getElementById('input-server-url').value.trim();\n  const collectorIdInput = document.getElementById('input-collector-id').value.trim();\n  const errBanner = document.getElementById('connect-error');\n\n  state.serverUrl = serverUrlInput.replace(/\\/+$/, '');\n  state.collectorId = collectorIdInput;\n\n  errBanner.classList.add('hidden');\n\n  try {\n    const regResp = await fetch(`${state.serverUrl}/api/v1/collector/auth/register`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        collector_id: state.collectorId,\n        device_id: navigator.userAgent,\n        app_version: '1.0.0-web',\n        device_model: 'Web Browser'\n      })\n    });\n\n    if (!regResp.ok) {\n      throw new Error(`Authentication error (${regResp.status})`);\n    }\n\n    const authData = await regResp.json();\n    state.authToken = authData.auth_token;\n\n    const connPill = document.getElementById('connection-pill');\n    connPill.textContent = state.collectorId;\n    connPill.className = 'badge badge-active';\n\n    await loadNextTask();\n  } catch (e) {\n    errBanner.textContent = `Connection failed: ${e.message}`;\n    errBanner.classList.remove('hidden');\n  }\n});\n\nasync function loadNextTask() {\n  try {\n    const taskResp = await fetch(`${state.serverUrl}/api/v1/collector/tasks/next?collector_id=${state.collectorId}`);\n    if (!taskResp.ok) throw new Error('Failed to dispense task');\n\n    const task = await taskResp.json();\n    if (!task) {\n      alert('No pending tasks available for this collector.');\n      return;\n    }\n\n    state.activeTask = task;\n\n    // Populate Task Screen\n    document.getElementById('task-run-title').textContent = `${task.experiment_id} • ${task.run_id}`;\n    document.getElementById('task-camera-sub').textContent = `Camera: ${task.camera_id} (1080p Landscape)`;\n\n    const scenBadge = document.getElementById('task-scenario-badge');\n    scenBadge.textContent = task.scenario_type.toUpperCase();\n    scenBadge.className = task.scenario_type.toLowerCase() === 'nominal' ? 'badge badge-nominal' : 'badge badge-fault';\n\n    document.getElementById('task-obj-val').textContent = task.required_object;\n    document.getElementById('task-tgt-val').textContent = task.target;\n    document.getElementById('task-dur-val').textContent = `${task.duration_min}–${task.duration_max}s`;\n    document.getElementById('task-proto-ver').textContent = task.instruction_version;\n\n    const stepsList = document.getElementById('task-steps-list');\n    stepsList.innerHTML = '';\n    task.procedure_steps.forEach(step => {\n      const li = document.createElement('li');\n      li.textContent = step.replace(/^\\d+\\.\\s*/, '');\n      stepsList.appendChild(li);\n    });\n\n    showScreen('task');\n  } catch (e) {\n    alert(`Task loading error: ${e.message}`);\n  }\n}\n\n// ----------------------------------------------------------------------------\n// Screen 2 -> Screen 3: Start Recording\n// ----------------------------------------------------------------------------\ndocument.getElementById('btn-start-recording').addEventListener('click', async () => {\n  try {\n    const viewfinder = document.getElementById('viewfinder');\n    await cameraManager.startCamera(viewfinder);\n\n    document.getElementById('hud-task-tag').textContent = \n      `${state.activeTask.experiment_id} • ${state.activeTask.run_id} • ${state.activeTask.camera_id}`;\n\n    showScreen('camera');\n\n    cameraManager.startRecording((secs) => {\n      const m = String(Math.floor(secs / 60)).padStart(2, '0');\n      const s = String(secs % 60).padStart(2, '0');\n      document.getElementById('rec-timer').textContent = `REC ${m}:${s}`;\n    });\n  } catch (e) {\n    alert(`Camera access failed: ${e.message}. Ensure camera permissions are allowed in browser.`);\n  }\n});\n\n// ----------------------------------------------------------------------------\n// Screen 3 -> Screen 4: Stop Recording & Validate\n// ----------------------------------------------------------------------------\ndocument.getElementById('btn-stop-recording').addEventListener('click', async () => {\n  const result = await cameraManager.stopRecording();\n  state.activeBlob = result.blob;\n  state.activeDuration = result.durationSeconds;\n\n  // Stash in IndexedDB immediately for fail-closed retention\n  const recordingId = `${state.activeTask.experiment_id}_${state.activeTask.run_id}_${state.activeTask.camera_id}`;\n  await storageManager.saveVideoBlob(recordingId, state.activeBlob, {\n    task: state.activeTask,\n    duration: state.activeDuration\n  });\n\n  // Setup Review Screen\n  const reviewPlayer = document.getElementById('review-player');\n  reviewPlayer.src = URL.createObjectURL(state.activeBlob);\n\n  document.getElementById('review-task-sub').textContent = \n    `${state.activeTask.experiment_id} • ${state.activeTask.run_id} • ${state.activeTask.camera_id}`;\n\n  const isDurationValid = state.activeDuration >= state.activeTask.duration_min && \n                          state.activeDuration <= state.activeTask.duration_max;\n\n  document.getElementById('val-duration').textContent = \n    `${state.activeDuration.toFixed(1)}s (required: ${state.activeTask.duration_min}–${state.activeTask.duration_max}s)`;\n  document.getElementById('icon-duration').textContent = isDurationValid ? '✓' : '⚠';\n  document.getElementById('icon-duration').style.color = isDurationValid ? 'var(--green-success)' : 'var(--amber-warning)';\n\n  const sizeMb = (state.activeBlob.size / (1024 * 1024)).toFixed(2);\n  document.getElementById('val-file-size').textContent = `${sizeMb} MB`;\n\n  document.getElementById('val-sha256').textContent = 'Computing streaming Web Crypto digest...';\n  document.getElementById('btn-upload').disabled = true;\n\n  showScreen('review');\n\n  // Compute SHA-256 digest\n  const hash = await ChecksumManager.computeSha256(state.activeBlob);\n  state.activeSha256 = hash;\n  document.getElementById('val-sha256').textContent = hash;\n  document.getElementById('btn-upload').disabled = false;\n});\n\n// Re-record Button\ndocument.getElementById('btn-rerecord').addEventListener('click', () => {\n  showScreen('task');\n});\n\n// ----------------------------------------------------------------------------\n// Screen 4 -> Screen 5: Resumable Chunked Upload\n// ----------------------------------------------------------------------------\ndocument.getElementById('btn-upload').addEventListener('click', async () => {\n  await executeUpload();\n});\n\ndocument.getElementById('btn-retry-upload').addEventListener('click', async () => {\n  await executeUpload();\n});\n\nasync function executeUpload() {\n  showScreen('upload');\n\n  const task = state.activeTask;\n  const blob = state.activeBlob;\n  const sha256 = state.activeSha256;\n\n  document.getElementById('upload-task-sub').textContent = `${task.experiment_id} • ${task.run_id} (${task.camera_id})`;\n  document.getElementById('upload-status-title').textContent = 'STREAMING RESUMABLE CHUNKS...';\n  document.getElementById('upload-error-box').classList.add('hidden');\n  document.getElementById('btn-retry-upload').classList.add('hidden');\n\n  const chunkSize = 3 * 1024 * 1024; // 3 MB (safe for Vercel 4.5 MB request limit)\n  const totalChunks = Math.ceil(blob.size / chunkSize);\n\n  const metadata = {\n    schema_version: '1.0',\n    experiment_id: task.experiment_id,\n    run_id: task.run_id,\n    recording_id: `${task.experiment_id}_${task.run_id}_${task.camera_id}`,\n    collector_id: state.collectorId,\n    camera_id: task.camera_id,\n    scenario_type: task.scenario_type,\n    object: task.required_object,\n    target: task.target,\n    duration_seconds: state.activeDuration,\n    width: 1920,\n    height: 1080,\n    fps: 30.0,\n    orientation: 'landscape',\n    file_size_bytes: blob.size,\n    sha256: sha256,\n    app_version: '1.0.0-web',\n    protocol_version: 'EXP001-v1.0',\n    created_at: new Date().toISOString()\n  };\n\n  try {\n    // 1. Initiate upload\n    const initResp = await fetch(`${state.serverUrl}/api/v1/collector/uploads/initiate`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        task_id: task.task_id,\n        collector_id: state.collectorId,\n        file_size_bytes: blob.size,\n        total_chunks: totalChunks,\n        sha256: sha256,\n        metadata: metadata\n      })\n    });\n\n    if (!initResp.ok) throw new Error(`Upload initiation rejected (${initResp.status})`);\n    const initData = await initResp.json();\n    state.activeUploadId = initData.upload_id;\n\n    // 2. Stream chunks sequentially\n    for (let chunkIdx = 0; chunkIdx < totalChunks; chunkIdx++) {\n      const start = chunkIdx * chunkSize;\n      const end = Math.min(start + chunkSize, blob.size);\n      const chunkBlob = blob.slice(start, end);\n      const chunkHash = await ChecksumManager.computeSha256(chunkBlob);\n\n      document.getElementById('upload-progress-chunk').textContent = `Chunk ${chunkIdx + 1} of ${totalChunks}`;\n      const percent = Math.round(((chunkIdx + 1) / totalChunks) * 100);\n      document.getElementById('upload-progress-fill').style.width = `${percent}%`;\n      document.getElementById('upload-progress-percent').textContent = `${percent}%`;\n\n      const chunkResp = await fetch(`${state.serverUrl}/api/v1/collector/uploads/${state.activeUploadId}/chunks/${chunkIdx}`, {\n        method: 'PUT',\n        headers: {\n          'Content-Type': 'application/octet-stream',\n          'X-Chunk-SHA256': chunkHash\n        },\n        body: chunkBlob\n      });\n\n      if (!chunkResp.ok) throw new Error(`Chunk ${chunkIdx} upload failed (${chunkResp.status})`);\n    }\n\n    // 3. Finalize & Verify Remote Persistence\n    document.getElementById('upload-status-title').textContent = 'VERIFYING REMOTE PERSISTENCE...';\n\n    const completeResp = await fetch(`${state.serverUrl}/api/v1/collector/uploads/${state.activeUploadId}/complete`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        upload_id: state.activeUploadId,\n        expected_sha256: sha256,\n        metadata: metadata\n      })\n    });\n\n    if (!completeResp.ok) throw new Error(`Completion error (${completeResp.status})`);\n    const completeData = await completeResp.json();\n\n    // 4. HARD INVARIANT CHECK\n    if (completeData.verified && String(completeData.status).toLowerCase() === 'verified') {\n      // Delete local temporary video ONLY after verified confirmation\n      const recordingId = `${task.experiment_id}_${task.run_id}_${task.camera_id}`;\n      await storageManager.deleteVerifiedVideo(recordingId, completeData.status, completeData.verified);\n\n      // Render Screen 6 (Complete)\n      document.getElementById('complete-task-sub').textContent = `${task.run_id} (${task.camera_id}) Complete`;\n      document.getElementById('complete-remote-path').textContent = completeData.remote_path;\n      showScreen('complete');\n    } else {\n      throw new Error(completeData.error_message || 'Verification rejected by backend.');\n    }\n\n  } catch (e) {\n    document.getElementById('upload-status-title').textContent = 'UPLOAD FAILED';\n    document.getElementById('upload-error-msg').textContent = e.message;\n    document.getElementById('upload-error-box').classList.remove('hidden');\n    document.getElementById('btn-retry-upload').classList.remove('hidden');\n  }\n}\n\n// ----------------------------------------------------------------------------\n// Screen 6: Next Task\n// ----------------------------------------------------------------------------\ndocument.getElementById('btn-next-task').addEventListener('click', async () => {\n  await loadNextTask();\n});\n"

MANIFEST_JSON = '{\n  "name": "ASTRA Collector",\n  "short_name": "Collector",\n  "description": "ASTRA-E Experimental Data Collection Terminal (Bhartiya Antariksh Station)",\n  "start_url": "/collector",\n  "display": "standalone",\n  "orientation": "landscape",\n  "background_color": "#0B0F19",\n  "theme_color": "#00E5FF",\n  "icons": [\n    {\n      "src": "/static/icon.png",\n      "sizes": "192x192",\n      "type": "image/png"\n    }\n  ]\n}\n'
